1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "selfLink", expression = "java(\"/api/owners/\" + owner.getId())")
22	    @Mapping(target = "displayName",
23	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
24	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
25	    @Mapping(target = "initials", expression = "java(initials(owner))")
26	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
27	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
28	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
29	    @Mapping(target = "locality", expression = "java(locality(owner))")
30	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
31	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
32	    @Mapping(target = "identityKey",
33	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.identityKey(owner))")
34	    @Mapping(target = "bulkSignupWarning",
35	            expression = "java(owner.getBulkSignupWarning() != null && owner.getBulkSignupWarning())")
36	    @Mapping(target = "capacityWarning",
37	            expression = "java(owner.getCapacityWarning() != null && owner.getCapacityWarning())")
38	    @Mapping(target = "possibleDuplicate",
39	            expression = "java(owner.getPossibleDuplicateOf() != null)")
40	    @Mapping(target = "deleted",
41	            expression = "java(owner.getDeleted() != null && owner.getDeleted())")
42	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
43	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
44	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
45	    OwnerDto toOwnerDto(Owner owner);
46	
47	    /** The stored E.164 'telephone' formatted for humans: the country code, a space, then the
48	     *  national digits grouped in threes (e.g. '+61 412 345 678'). The raw 'telephone' stays
49	     *  E.164. Null when the stored value is not a recognised E.164 number. */
50	    default String telephoneDisplay(Owner owner) {
51	        return org.springframework.samples.petclinic.rest.function.owner.E164Telephone
52	                .toDisplayOrNull(owner.getTelephone());
53	    }
54	
55	    /** Age band derived from birthDate relative to registrationDate: 'MINOR' when under
56	     *  18, 'ADULT' from 18 to 64, 'SENIOR' at 65 or over. Null when either date is absent. */
57	    default String ageBand(Owner owner) {
58	        if (owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
59	            return null;
60	        }
61	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
62	        if (age < 18) {
63	            return "MINOR";
64	        }
65	        if (age < 65) {
66	            return "ADULT";
67	        }
68	        return "SENIOR";
69	    }
70	
71	    /** 'EMAIL' when the owner has a non-blank email address, otherwise 'PHONE'. */
72	    default String contactPreference(Owner owner) {
73	        return owner.getEmail() != null && !owner.getEmail().isBlank() ? "EMAIL" : "PHONE";
74	    }
75	
76	    /** The owner's salutation: 'title' + ' ' + lastName when a title is present, else just the
77	     *  lastName. */
78	    default String salutation(Owner owner) {
79	        String title = owner.getTitle();
80	        if (title != null && !title.isBlank()) {
81	            return title + " " + owner.getLastName();
82	        }
83	        return owner.getLastName();
84	    }
85	
86	    /** Upper-cased first letters of firstName and lastName, dot-separated with a trailing dot. */
87	    default String initials(Owner owner) {
88	        return owner.getFirstName().substring(0, 1).toUpperCase()
89	                + "." + owner.getLastName().substring(0, 1).toUpperCase() + ".";
90	    }
91	
92	    /** The fiscal year of the (business-day-adjusted) registrationDate as 'FY<YY>',
93	     *  where the fiscal year starts on 1 July and is labelled by the calendar year in
94	     *  which it ends (e.g. 2 Jul 2025 -> FY26, 30 Jun 2026 -> FY26). Null when there is
95	     *  no registrationDate. */
96	    default String fiscalYear(Owner owner) {
97	        if (owner.getRegistrationDate() == null) {
98	            return null;
99	        }
100	        return String.format("FY%02d", fiscalYearOf(owner.getRegistrationDate()) % 100);
101	    }
102	
103	    /** The calendar year in which the fiscal year containing {@code date} ends. The fiscal
104	     *  year starts on 1 July, so July-December fall in the fiscal year ending the following
105	     *  calendar year, and January-June in the one ending the current year. */
106	    static int fiscalYearOf(java.time.LocalDate date) {
107	        return date.getMonthValue() >= java.time.Month.JULY.getValue()
108	                ? date.getYear() + 1 : date.getYear();
109	    }
110	
111	    /** Membership points: starts at 0, adds 2 when an email is present, adds 1 when
112	     *  namesakeCount is 0, adds 2 for a household of 3 or more, and adds 3 for tenure
113	     *  (at least one elapsed fiscal year between the registrationDate and today, the
114	     *  fiscal year starting 1 July). */
115	    default Integer membershipPoints(Owner owner) {
116	        int points = 0;
117	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
118	        if (hasEmail) {
119	            points += 2;
120	        }
121	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
122	            points += 1;
123	        }
124	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
125	            points += 2;
126	        }
127	        if (owner.getRegistrationDate() != null
128	                && fiscalYearOf(java.time.LocalDate.now())
129	                        - fiscalYearOf(owner.getRegistrationDate()) >= 1) {
130	            points += 3;
131	        }
132	        return points;
133	    }
134	
135	    /** Numeric membership level from 1 to 4, mapped from membershipPoints: level 1 for
136	     *  0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more. Clamped to the owner's
137	     *  {@code membershipLevelCap} when present, so a new owner's level cannot exceed one
138	     *  above the maximum among their household members at creation. */
139	    default Integer membershipLevel(Owner owner) {
140	        int level = uncappedMembershipLevel(owner);
141	        Integer cap = owner.getMembershipLevelCap();
142	        if (cap != null && level > cap) {
143	            return cap;
144	        }
145	        return level;
146	    }
147	
148	    /** The membership level derived purely from membershipPoints, before any
149	     *  household-derived ceiling is applied. */
150	    default Integer uncappedMembershipLevel(Owner owner) {
151	        int points = membershipPoints(owner);
152	        if (points <= 1) {
153	            return 1;
154	        }
155	        if (points <= 3) {
156	            return 2;
157	        }
158	        if (points <= 5) {
159	            return 3;
160	        }
161	        return 4;
162	    }
163	
164	    /** The owner's locality: the REGION prefix of the memberId ('<REGION><FY><HASH8><CHK>'),
165	     *  which is derived from the postcode at creation. 'UNKNOWN' when the memberId is absent or
166	     *  carries no known region prefix. Derived from the same region-and-hash identity as the
167	     *  memberId so it always agrees with it. */
168	    default String locality(Owner owner) {
169	        String id = owner.getMemberId();
170	        if (id != null) {
171	            for (String region : new String[] {"NSW", "VIC", "QLD"}) {
172	                if (id.startsWith(region)) {
173	                    return region;
174	                }
175	            }
176	        }
177	        return "UNKNOWN";
178	    }
179	
180	    /** The owner's segment, formatted '<TIER>_<AREA>': TIER is 'PREMIUM' when
181	     *  membershipLevel is 3 or more, otherwise 'STANDARD'; AREA is 'METRO' when the
182	     *  locality is a known region (NSW, VIC or QLD), otherwise 'REGIONAL'. */
183	    default String ownerSegment(Owner owner) {
184	        Integer level = membershipLevel(owner);
185	        String tier = level != null && level >= 3 ? "PREMIUM" : "STANDARD";
186	        String area = org.springframework.samples.petclinic.rest.function.owner.PostcodeRegions
187	                .timezoneForRegion(locality(owner)) != null ? "METRO" : "REGIONAL";
188	        return tier + "_" + area;
189	    }
190	
191	    /** The IANA timezone name derived from the owner's locality/region using the fixed
192	     *  region-to-timezone table (NSW->Australia/Sydney, VIC->Australia/Melbourne,
193	     *  QLD->Australia/Brisbane). Null when the locality is not a region in the table. */
194	    default String timezone(Owner owner) {
195	        return org.springframework.samples.petclinic.rest.function.owner.PostcodeRegions
196	                .timezoneForRegion(locality(owner));
197	    }
198	
199	    Owner toOwner(OwnerDto ownerDto);
200	
201	    @Mapping(target = "id", ignore = true)
202	    @Mapping(target = "pets", ignore = true)
203	    Owner toOwner(OwnerFieldsDto ownerDto);
204	
205	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
206	
207	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
208	
209	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
210	        OwnerPageDto ownerPageDto = new OwnerPageDto();
211	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
212	        ownerPageDto.setPage(ownerPage.getNumber());
213	        ownerPageDto.setSize(ownerPage.getSize());
214	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
215	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
216	        return ownerPageDto;
217	    }
218	}
